create function private.enforce_inspection_image_limit() returns trigger language plpgsql security definer set search_path='' as $$ begin if (select count(*) from public.inspection_report_images where inspection_report_id=new.inspection_report_id) >= 25 then raise exception 'An inspection report can contain at most 25 images'; end if; return new; end; $$;
create trigger inspection_report_images_limit before insert on public.inspection_report_images for each row execute function private.enforce_inspection_image_limit();
create or replace function public.submit_inspection_report(p_request_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.employee_assignments where verification_request_id=p_request_id and employee_id=auth.uid() and status='in_progress') then raise exception 'Assigned inspector required'; end if; if not exists(select 1 from public.inspection_reports where verification_request_id=p_request_id and inspector_id=auth.uid() and overall_result is not null and char_length(trim(coalesce(summary,''))) >= 20 and body_condition is not null and tyre_condition is not null and engine_condition is not null) or not exists(select 1 from public.inspection_report_images i join public.inspection_reports r on r.id=i.inspection_report_id where r.verification_request_id=p_request_id) then raise exception 'Complete the report and add evidence before submission'; end if; update public.inspection_reports set submitted_at=now() where verification_request_id=p_request_id; update public.verification_requests set status='report_submitted',report_submitted_at=now() where id=p_request_id and status='inspection_in_progress'; if not found then raise exception 'Invalid transition'; end if; end; $$;
create or replace function public.finalise_verification(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_car uuid; declare v_completed timestamptz:=now(); begin if not(select private.is_admin()) then raise exception 'Admin access required'; end if; select car_id into v_car from public.verification_requests where id=p_id and status='report_submitted'; if not found or not exists(select 1 from public.inspection_reports where verification_request_id=p_id and submitted_at is not null) then raise exception 'Submitted report required'; end if; update public.verification_requests set status='completed',completed_at=v_completed where id=p_id; update public.employee_assignments set status='completed',completed_at=v_completed where verification_request_id=p_id and status='in_progress'; update public.inspection_report_images set evidence_expires_at=v_completed+interval '90 days' where inspection_report_id in(select id from public.inspection_reports where verification_request_id=p_id); if v_car is not null then update public.cars set is_verified=true,verified_at=v_completed,verified_verification_request_id=p_id where id=v_car and status='active'; end if; end; $$;
revoke execute on function public.submit_inspection_report(uuid),public.finalise_verification(uuid) from anon;
